class native_driver extends uvm_driver #(native_transaction);
  `uvm_component_utils(native_driver)
  virtual native_if bus;
  function new(string name,uvm_component parent); super.new(name,parent); endfunction
  function void build_phase(uvm_phase phase);
    if(!uvm_config_db#(virtual native_if)::get(this,"","bus",bus)) `uvm_fatal("IF","missing bus")
  endfunction
  task run_phase(uvm_phase phase);
    forever begin
      seq_item_port.get_next_item(req);
      bus.drive=req.drive; bus.tag=req.tag;
      #2;
      if(req.sample) begin bus.pending++; ->bus.sample_event; end
      #1;
      seq_item_port.item_done();
    end
  endtask
endclass
class native_monitor extends uvm_monitor;
  `uvm_component_utils(native_monitor)
  virtual native_if bus;
  uvm_analysis_port #(native_transaction) observations;
  function new(string name,uvm_component parent); super.new(name,parent); observations=new("observations",this); endfunction
  function void build_phase(uvm_phase phase);
    if(!uvm_config_db#(virtual native_if)::get(this,"","bus",bus)) `uvm_fatal("IF","missing bus")
  endfunction
  task run_phase(uvm_phase phase);
    forever begin
      native_transaction observed;
      @bus.sample_event;
      observed=native_transaction::type_id::create("observed");
      observed.actual=bus.actual; observed.drive=bus.drive; observed.tag=bus.tag;
      observations.write(observed); bus.pending--;
    end
  endtask
endclass
class native_predictor extends uvm_subscriber #(native_transaction);
  `uvm_component_utils(native_predictor)
  virtual native_if bus;
  uvm_analysis_port #(native_transaction) predictions;
  function new(string name,uvm_component parent); super.new(name,parent); predictions=new("predictions",this); endfunction
  function void build_phase(uvm_phase phase);
    if(!uvm_config_db#(virtual native_if)::get(this,"","bus",bus)) `uvm_fatal("IF","missing bus")
  endfunction
  function void write(native_transaction item);
    item.expected=bus.predicted;
    predictions.write(item);
  endfunction
endclass
class native_scoreboard extends uvm_subscriber #(native_transaction);
  `uvm_component_utils(native_scoreboard)
  int unsigned comparisons, mismatches;
  function new(string name,uvm_component parent); super.new(name,parent); endfunction
  function void write(native_transaction item);
    comparisons++;
    if(item.actual !== item.expected) begin
      mismatches++;
      if(mismatches<=20) `uvm_error("COMPARE",$sformatf("point=%0d tag=%0d actual=%h expected=%h",comparisons,item.tag,item.actual,item.expected))
    end
  endfunction
  function void check_phase(uvm_phase phase);
    if(comparisons<100) `uvm_error("VACUITY","insufficient observable comparisons")
  endfunction
endclass
class native_checker extends uvm_component;
  `uvm_component_utils(native_checker)
  virtual native_if bus;
  function new(string name,uvm_component parent); super.new(name,parent); endfunction
  function void build_phase(uvm_phase phase);
    if(!uvm_config_db#(virtual native_if)::get(this,"","bus",bus)) `uvm_fatal("IF","missing bus")
  endfunction
  function void check_phase(uvm_phase phase);
    if(bus.pending!=0) `uvm_error("DRAIN","observations not drained")
  endfunction
endclass
class native_coverage extends uvm_subscriber #(native_transaction);
  `uvm_component_utils(native_coverage)
  virtual native_if bus;
  int unsigned event_kind;
  int mask_count, mask_index, read_enabled, write_enabled, read_address, write_address;
  covergroup input_history;
    option.per_instance=1;
    event_class: coverpoint event_kind { bins scenarios[]={[0:6]}; }
    mask_size: coverpoint mask_count { bins zero={0}; bins one={1}; bins partial={[2:335]}; bins all_bits={336}; }
mask_position: coverpoint mask_index iff(mask_count==1) { bins positions[]={[0:335]}; }
read_enable: coverpoint read_enabled { bins off={0}; bins on={1}; }
write_enable: coverpoint write_enabled { bins off={0}; bins on={1}; }
read_word: coverpoint read_address { bins words[]={0,1}; }
write_word: coverpoint write_address { bins words[]={0,1}; }
write_mask: cross mask_size, write_enable;
address_isolation: cross read_word, write_word;
  endgroup
  function new(string name,uvm_component parent); super.new(name,parent); input_history=new; endfunction
  function void build_phase(uvm_phase phase);
    if(!uvm_config_db#(virtual native_if)::get(this,"","bus",bus)) `uvm_fatal("IF","missing bus")
  endfunction
  function void write(native_transaction item);
    event_kind=item.tag & 255;
    mask_count=$countones(bus.W0_mask); mask_index=0;
for(int position=0;position<336;position++) if(bus.W0_mask[position]) mask_index=position;
read_enabled=bus.R0_en; write_enabled=bus.W0_en; read_address=bus.R0_addr; write_address=bus.W0_addr;
    input_history.sample();
  endfunction
endclass
class native_env extends uvm_env;
  `uvm_component_utils(native_env)
  uvm_sequencer #(native_transaction) sequencer;
  native_driver driver;
  native_monitor monitor;
  native_predictor predictor;
  native_scoreboard scoreboard;
  native_checker checker;
  native_coverage coverage;
  function new(string name,uvm_component parent); super.new(name,parent); endfunction
  function void build_phase(uvm_phase phase);
    sequencer=new("sequencer",this);
    driver=native_driver::type_id::create("driver",this);
    monitor=native_monitor::type_id::create("monitor",this);
    predictor=native_predictor::type_id::create("predictor",this);
    scoreboard=native_scoreboard::type_id::create("scoreboard",this);
    checker=native_checker::type_id::create("checker",this);
    coverage=native_coverage::type_id::create("coverage",this);
  endfunction
  function void connect_phase(uvm_phase phase);
    driver.seq_item_port.connect(sequencer.seq_item_export);
    monitor.observations.connect(predictor.analysis_export);
    monitor.observations.connect(coverage.analysis_export);
    predictor.predictions.connect(scoreboard.analysis_export);
  endfunction
endclass
class dvbench_test extends uvm_test;
  `uvm_component_utils(dvbench_test)
  native_env env;
  function new(string name,uvm_component parent); super.new(name,parent); endfunction
  function void build_phase(uvm_phase phase); env=native_env::type_id::create("env",this); endfunction
  task run_phase(uvm_phase phase);
    native_sequence sequence_object=native_sequence::type_id::create("sequence_object");
    phase.raise_objection(this); sequence_object.start(env.sequencer); #3; phase.drop_objection(this);
  endtask
  function void report_phase(uvm_phase phase);
    uvm_report_server server=uvm_report_server::get_server();
    if(server.get_severity_count(UVM_ERROR)==0 && server.get_severity_count(UVM_FATAL)==0 && env.scoreboard.comparisons>=100)
      $display("DVBench_COMPLETED");
    $display("REFERENCE_POINTS=%0d MISMATCHES=%0d",env.scoreboard.comparisons,env.scoreboard.mismatches);
  endfunction
endclass
endpackage
